from mk import *
from lib import fbd
STRICT["on"] = True

def fig():
    g = Fig(560, 200, "מסילה: רבע מעגל PQ ברדיוס 20 סנטימטר, וקטע ישר QS. כדור A משוחרר בנקודה P, וכדור B במנוחה בנקודה S")
    g.path("M 80,40 A 110 110 0 0 0 190,150 L 470,150", width=3)
    g.dot(80, 40); g.ball(88, 38, 9); g.text(70, 40, "P", anchor="end"); g.text(96, 22, "A")
    g.dot(190, 150); g.text(190, 172, "Q"); g.ball(420, 141, 8); g.text(420, 172, "S"); g.text(420, 122, "B")
    g.line(190, 40, 80, 40, stroke="var(--d-dim)", width=1, dash="3 3"); g.line(190, 40, 190, 150, stroke="var(--d-dim)", width=1, dash="3 3")
    g.text(170, 90, "r", anchor="end")
    return g

E(id="bagrut-1986-q3", year=1986, label="1986 שאלה 3", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"כדור $A$ מחליק בלי חיכוך לאורך מסילה מעגלית $PQ$, שממשיכה בקטע ישר $QS$. הכדור מתנגש בכדור $B$, שעומד בנקודה $S$, בקצה הקטע הישר. המסילה $PQ$ היא רבע מעגל שרדיוסו $r = 20\,\text{cm}$. מסת הכדור $A$: $m_A = 60\,\text{g}$. מסת הכדור $B$: $m_B = 20\,\text{g}$. משחררים את הכדור $A$ ממנוחה בנקודה $P$.",
  parts=[
    P("א", r"מה המהירות של הכדורים אחרי ההתנגשות, אם ההתנגשות פלסטית? ואם ההתנגשות אלסטית ומצחית, מה המהירות של $A$ ומה המהירות של $B$ אחריה?", multi((r"התנגשות פלסטית: המהירות המשותפת", 1.5, "m/s"), (r"התנגשות אלסטית: המהירות של A", 1, "m/s"), (r"התנגשות אלסטית: המהירות של B", 3, "m/s")), ["principle", "algebra"], [
        X(r"אין חיכוך, ולכן במסילה האנרגיה המכנית נשמרת. בהתנגשות עצמה הכוחות בין הכדורים פנימיים, ולכן התנע נשמר. הכיוון החיובי הוא כיוון התנועה של A."),
        S(r"המהירות של A לפני ההתנגשות", r"שימור אנרגיה: הכדור יורד את הרדיוס", r"m_A g r = \tfrac{1}{2} m_A v_A^2 \;\Rightarrow\; v_A = \sqrt{2 \cdot 10 \cdot 0.2} = 2\,\text{m/s}", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
        S(r"התנגשות פלסטית: שימור תנע", r"אחרי ההתנגשות הכדורים נעים יחד. ממירים גרמים לקילוגרמים", r"0.06 \cdot 2 + 0 = (0.06 + 0.02)\,u \;\Rightarrow\; u = \frac{0.12}{0.08} = 1.5\,\text{m/s}", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"התנגשות אלסטית: שימור תנע", r"כל כדור במהירות שלו", r"0.06 \cdot 2 + 0 = 0.06\,u_A + 0.02\,u_B"),
        S(r"התנגשות אלסטית: המהירויות היחסיות", r"בהתנגשות אלסטית חד-ממדית, מהירות ההתקרבות שווה למהירות ההתרחקות", r"2 - 0 = -(u_A - u_B) \;\Rightarrow\; u_B = u_A + 2", eq=r"v_A - v_B = -(u_A - u_B)"),
        S(r"פותרים את שתי המשוואות", r"מציבים את המשוואה השנייה בראשונה", r"0.12 = 0.06\,u_A + 0.02\,(u_A + 2) \;\Rightarrow\; 0.08\,u_A = 0.08 \;\Rightarrow\; u_A = 1\,\text{m/s},\quad u_B = 3\,\text{m/s}"),
        C(r"בדיקה: שימור אנרגיה", r"בהתנגשות אלסטית האנרגיה הקינטית לפני שווה לאחרי", r"\tfrac{1}{2} \cdot 0.06 \cdot 4 = 0.12\,\text{J} = \tfrac{1}{2} \cdot 0.06 \cdot 1 + \tfrac{1}{2} \cdot 0.02 \cdot 9 \;\checkmark"),
    ], r"פלסטית: $1.5\,\text{m/s}$. אלסטית: $A$ ב-$1\,\text{m/s}$ ו-$B$ ב-$3\,\text{m/s}$, שניהם באותו כיוון", key=r"1.5 m/s ; uA=1 m/s ; uB=3 m/s"),
    P("ב", r"ההתנגשות אלסטית אבל לא מצחית, והכדור $A$ ממשיך בכיוון שיוצר זווית $\alpha$ עם כיוון התנועה שלו לפני ההתנגשות. כתבו את המשוואות שמאפשרות לחשב את המהירות של כל אחד מהכדורים, והסבירו אותן. אין צורך לפתור.", OPEN, ["principle"], [
        X(r"נסמן באות בטא את הזווית של הכדור B עם הכיוון המקורי. ציר x הוא הכיוון המקורי, וציר y ניצב לו."),
        S(r"שימור תנע בציר x", r"אין כוחות חיצוניים אופקיים בזמן ההתנגשות", r"m_A v_A = m_A u_A\cos\alpha + m_B u_B\cos\beta", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"שימור תנע בציר y", r"לפני ההתנגשות אין תנע בכיוון הזה. הכדורים יוצאים לשני צדדים הפוכים", r"0 = m_A u_A\sin\alpha - m_B u_B\sin\beta"),
        S(r"שימור אנרגיה", r"ההתנגשות אלסטית", r"\tfrac{1}{2}m_A v_A^2 = \tfrac{1}{2}m_A u_A^2 + \tfrac{1}{2}m_B u_B^2", eq=r"E_k = \tfrac{1}{2}mv^2"),
    ], r"שתי משוואות תנע (רכיבים) ומשוואת אנרגיה, לשלושה נעלמים $u_A$, $u_B$, $\beta$"),
  ],
  concepts=["שימור אנרגיה", "התנגשות פלסטית", "התנגשות אלסטית", "שימור תנע ברכיבים"],
  summary=r"כדור שגולש ברבע מעגל ומתנגש בכדור שני: מהירויות אחרי התנגשות פלסטית ואלסטית, ומשוואות להתנגשות לא מצחית.",
  review="הנחה שלי.\nסעיף א הוא סעיף אחד, כמו במקור, עם שלוש תיבות.\nמה לבדוק: רק לאשר.")
